<?php require 'config.php';
if(isset($_GET['logout'])){unset($_SESSION['admin']);header('Location: admin.php');exit;}
if(!isset($_SESSION['admin'])){
 if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("SELECT * FROM admins WHERE username=? AND password=?");$s->execute([$_POST['username'],$_POST['password']]);if($s->fetch()){$_SESSION['admin']=1;header('Location: admin.php');exit;}$error='زانیارییەکان هەڵەن.';}
 ?><!DOCTYPE html><html lang="ku" dir="rtl"><head><meta charset="UTF-8"><link rel="stylesheet" href="assets/style.css"><title>بەڕێوەبەر</title></head><body><div class="login"><h1>چوونەژوورەوەی بەڕێوەبەر</h1><?php if(isset($error))echo "<p>$error</p>";?><form method="post"><input name="username" placeholder="بەکارهێنەر"><input type="password" name="password" placeholder="وشەی نهێنی"><button class="btn">چوونەژوورەوە</button></form><p>admin / admin123</p></div></body></html><?php exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO products(category_id,name,description,price,image) VALUES(?,?,?,?,?)")->execute([(int)$_POST['category_id'],$_POST['name'],$_POST['description'],$_POST['price'],$_POST['image']]);header('Location: admin.php');exit;}
$cats=$pdo->query("SELECT * FROM categories")->fetchAll();$products=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();$orders=$pdo->query("SELECT * FROM orders ORDER BY id DESC")->fetchAll();
?>
<!DOCTYPE html><html lang="ku" dir="rtl"><head><meta charset="UTF-8"><link rel="stylesheet" href="assets/style.css"><title>داشبۆرد</title></head><body><main class="container"><div class="section-title"><h1>داشبۆردی بەڕێوەبەر</h1><a class="btn" href="admin.php?logout=1">دەرچوون</a></div><h2>زیادکردنی کاڵای نوێ</h2><form class="form" method="post"><label>ناوی کاڵا<input required name="name"></label><label>بەش<select name="category_id"><?php foreach($cats as $c)echo "<option value='{$c['id']}'>".htmlspecialchars($c['name'])."</option>";?></select></label><label>نرخ<input required type="number" step="0.01" name="price"></label><label>لینکی وێنە<input name="image"></label><label>وردەکاری<textarea name="description"></textarea></label><button class="btn">زیادکردن</button></form><h2>کاڵاکان</h2><table><tr><th>ناو</th><th>بەش</th><th>نرخ</th></tr><?php foreach($products as $p):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['category'])?></td><td><?=number_format($p['price'],2)?> $</td></tr><?php endforeach;?></table><h2>داواکارییەکان</h2><table><tr><th>#</th><th>کڕیار</th><th>مۆبایل</th><th>کۆی گشتی</th></tr><?php foreach($orders as $o):?><tr><td><?=$o['id']?></td><td><?=htmlspecialchars($o['customer_name'])?></td><td><?=htmlspecialchars($o['phone'])?></td><td><?=number_format($o['total'],2)?> $</td></tr><?php endforeach;?></table></main></body></html>